 void loadApps(){apps.clear();try{for(LauncherActivityInfo a:launcher.getActivityList(null,android.os.Process.myUserHandle()))if(!a.getComponentName().getPackageName().equals(getPackageName()))apps.add(new App(a));}catch(Exception e){toast("Не удалось прочитать приложения");}Collections.sort(apps,(a,b)->a.name.compareToIgnoreCase(b.name));}
