 void makeDesk(){desk=new FrameLayout(this);desk.setLayoutParams(new FrameLayout.LayoutParams(-1,-1));LinearLayout head=new LinearLayout(this);head.setOrientation(1);head.setGravity(Gravity.CENTER);time=text("",58);date=text("",13);head.addView(time);head.addView(date);desk.addView(head,new FrameLayout.LayoutParams(-1,dp(145),Gravity.TOP));canvas=new FrameLayout(this);FrameLayout.LayoutParams cp=new FrameLayout.LayoutParams(-1,-1);cp.topMargin=dp(155);cp.bottomMargin=dp(22);desk.addView(canvas,cp);TextView hint=text("Удерживай ярлык для перемещения и изменения размера",10);hint.setGravity(Gravity.CENTER);desk.addView(hint,new FrameLayout.LayoutParams(-1,dp(20),Gravity.BOTTOM));tools=new LinearLayout(this);tools.setBackground(bg(PANEL,14));tools.addView(btn("−",()->resize(.9f)));tools.addView(btn("＋",()->resize(1.1f)));tools.addView(btn("Удалить",()->remove()));tools.addView(btn("✓",()->{edit=false;select(null);}));tools.setVisibility(View.GONE);desk.addView(tools,new FrameLayout.LayoutParams(-2,dp(48),Gravity.TOP|Gravity.CENTER_HORIZONTAL));}
 void makeDock(){dock=new FrameLayout(this);dock.setBackground(bg(PANEL,24));FrameLayout.LayoutParams d=new FrameLayout.LayoutParams(-1,dp(74),Gravity.BOTTOM);d.setMargins(dp(10),0,dp(10),dp(14));root.addView(dock,d);pill=new View(this);pill.setBackground(bg(accent,18));FrameLayout.LayoutParams pp=new FrameLayout.LayoutParams(dp(80),dp(58));pp.topMargin=dp(8);dock.addView(pill,pp);LinearLayout row=new LinearLayout(this);dock.addView(row,new FrameLayout.LayoutParams(-1,-1));String[] names={"⌂\nРабочий стол","⚙\nНастройки","▦\nПриложения","◇\nКастомизация"};for(int n=0;n<4;n++){final int k=n;TextView b=text(names[n],11);b.setGravity(Gravity.CENTER);tabs[n]=b;row.addView(b,new LinearLayout.LayoutParams(0,-1,1));b.setOnClickListener(v->showPage(k));}dock.addOnLayoutChangeListener((v,l,t,r,b,ol,ot,or_,ob)->movePill(false));}
 void movePill(boolean animated){if(dock.getWidth()==0)return;int w=dock.getWidth()/4;FrameLayout.LayoutParams p=(FrameLayout.LayoutParams)pill.getLayoutParams();p.width=w-dp(8);pill.setLayoutParams(p);float x=tab*w+dp(4);pill.animate().cancel();if(animated)pill.animate().translationX(x).setDuration(duration(340)).setInterpolator(new PathInterpolator(.2f,.8f,.2f,1)).start();else pill.setTranslationX(x);for(int n=0;n<4;n++)tabs[n].setTextColor(n==tab?0xff211b15:0xffaaa49c);}
 void showPage(int n){if(n==tab){if(n==0)render();return;}int dir=n>tab?1:-1;tab=n;final int token=++transition;movePill(true);FrameLayout old=page;for(int k=stage.getChildCount()-1;k>=0;k--){View v=stage.getChildAt(k);v.animate().cancel();if(v!=old)stage.removeView(v);}FrameLayout next=n==0?desk:new FrameLayout(this);if(next.getParent()!=null)((android.view.ViewGroup)next.getParent()).removeView(next);next.setAlpha(1);next.setTranslationX(0);if(n==1)settings(next);if(n==2)appList(next);if(n==3)custom(next);stage.addView(next,new FrameLayout.LayoutParams(-1,-1));page=next;if(n==0)next.post(()->render());if(motion){old.setImportantForAccessibility(View.IMPORTANT_FOR_ACCESSIBILITY_NO_HIDE_DESCENDANTS);next.setAlpha(0);next.setTranslationX(dp(38)*dir);next.animate().alpha(1).translationX(0).setDuration(340).setInterpolator(new PathInterpolator(.22f,.8f,.25f,1)).start();old.animate().alpha(0).translationX(-dp(28)*dir).setDuration(340).withEndAction(()->{if(token==transition&&old!=page){stage.removeView(old);old.setAlpha(1);old.setTranslationX(0);}}).start();}else stage.removeView(old);next.setImportantForAccessibility(View.IMPORTANT_FOR_ACCESSIBILITY_AUTO);}
